export type ErrorState = { code: string; message: string; details?: unknown } | null;

type TarefasPage = Output<'tarefas.tarefas_equipe.listarTarefasEquipe'>['tarefas'];

/** Filters of the team task list; every leaf is null when the filter is not applied. */
export type FiltrosEquipe = {
