  'ui.tarefas.tarefas_equipe.buscarResponsaveisDisponiveisStatus': 'buscarResponsaveisDisponiveisStatus',
  'ui.tarefas.tarefas_equipe.buscarResponsaveisDisponiveisError': 'buscarResponsaveisDisponiveisError',
  'ui.tarefas.tarefas_equipe.trocarResponsavelTarefaStatus': 'trocarResponsavelTarefaStatus',
  'ui.tarefas.tarefas_equipe.trocarResponsavelTarefaError': 'trocarResponsavelTarefaError',
  'ui.tarefas.tarefas_equipe.cancelarTarefaEquipeStatus': 'cancelarTarefaEquipeStatus',
  'ui.tarefas.tarefas_equipe.cancelarTarefaEquipeError': 'cancelarTarefaEquipeError',
  'ui.tarefas.tarefas_equipe.scenary': 'scenary',
};
const STATE_KEYS = Object.keys(STATE_MEMBER_BY_KEY);

const DATA_KEYS: string[] = [
  'ui.tarefas.tarefas_equipe.tarefas',
  'ui.tarefas.tarefas_equipe.contagemPorSituacao',
  'ui.tarefas.tarefas_equipe.listas',
  'ui.tarefas.tarefas_equipe.carregarFiltrosEquipeParticipantes',
  'ui.tarefas.tarefas_equipe.tarefa',
  'ui.tarefas.tarefas_equipe.buscarResponsaveisDisponiveisParticipantes',
];

const PAGE_ROUTE_SUFFIX = '/tarefas/tarefas_equipe';
const PAGE_SIZE = 50;

type EntryParams = {
  tarefaId: string | null;
  listaTarefasId: string | null;
  responsavelId: string | null;
};

function emptyFiltros(): FiltrosEquipe {
  return { listaId: null, responsavelId: null, prioridade: null, status: null, prazoDe: null, prazoAte: null };
}

function emptyTrocarResponsavelTarefaDraft(): TrocarResponsavelTarefaDraft {
  return { responsavelId: null };
}

export class TarefasTarefas_equipeShared extends StateLitElement {
  /** state tarefas — the page of team tasks in summary form (list, assignee, who acts now, due marks already computed); source listarTarefasEquipe.tarefas; organism tarefasEquipe */
  @property({ attribute: false }) tarefas: TarefasPage | null = null;

  /** state contagemPorSituacao — number of tasks in each status under the applied filters; source listarTarefasEquipe.contagemPorSituacao; organism tarefasEquipe */
  @property({ attribute: false }) contagemPorSituacao: ContagemSituacao[] = [];

  /** state listas — task lists identified by name, options of the list filter; source carregarFiltrosEquipe.listas; organism tarefasEquipe */
  @property({ attribute: false }) listas: ListaOpcao[] = [];

  /** state carregarFiltrosEquipeParticipantes — module participants identified by name, with platform status and whether they accept tasks, options of the assignee filter; source carregarFiltrosEquipe.participantes; organism tarefasEquipe */
  @property({ attribute: false }) carregarFiltrosEquipeParticipantes: ParticipanteOpcao[] = [];

  /** state tarefa — the opened task with list, assignee, creator, who acts now, subtasks, ordered checklist and event history (the selected record); source obterTarefaEquipe.tarefa; organisms tarefaAcoes, tarefaDetalhe, tarefaHistorico */
  @property({ attribute: false }) tarefa: TarefaDetalhe | null = null;

  /** state buscarResponsaveisDisponiveisParticipantes — eligible participants found by name to become the new assignee; source buscarResponsaveisDisponiveis.participantes; organism tarefaAcoes */
  @property({ attribute: false }) buscarResponsaveisDisponiveisParticipantes: ParticipanteOpcao[] = [];

  /** state selectedTarefa — the id of the task selected in tarefasEquipe (the record is in tarefa); source entry.params.tarefaId; organisms tarefaDetalhe, tarefasEquipe; lives in the URL */
  @property({ attribute: false }) selectedTarefa: string | null = null;

  /** state filtrosEquipe — draft of the list filters (list, assignee, priority, status, due range); the list id comes from entry param listaTarefasId; source filtrosEquipe (completed gap); organism tarefasEquipe */
  @property({ attribute: false }) filtrosEquipe: FiltrosEquipe = emptyFiltros();

  /** state trocarResponsavelTarefaDraft — draft of the reassign command (chosen new assignee id), prefilled from entry param responsavelId; source trocarResponsavelTarefa.input; organism tarefaAcoes */
  @property({ attribute: false }) trocarResponsavelTarefaDraft: TrocarResponsavelTarefaDraft = emptyTrocarResponsavelTarefaDraft();

  /** state pageStatus — overall status of the page opening (filters and list loaded); source page */
  @property({ attribute: false }) pageStatus: 'idle' | 'loading' | 'empty' | 'success' | 'error' = 'idle';

  /** state carregarFiltrosEquipeStatus — status of the filter options request; source carregarFiltrosEquipe */
  @property({ attribute: false }) carregarFiltrosEquipeStatus: 'idle' | 'loading' | 'success' | 'error' = 'idle';

  /** state carregarFiltrosEquipeError — error of the filter options request, null when none; source carregarFiltrosEquipe */
  @property({ attribute: false }) carregarFiltrosEquipeError: ErrorState = null;

  /** state listarTarefasEquipeStatus — status of the task list request; source listarTarefasEquipe */
  @property({ attribute: false }) listarTarefasEquipeStatus: 'idle' | 'loading' | 'success' | 'error' = 'idle';

  /** state listarTarefasEquipeError — error of the task list request, null when none; source listarTarefasEquipe */
  @property({ attribute: false }) listarTarefasEquipeError: ErrorState = null;

  /** state obterTarefaEquipeStatus — status of the open task request; source obterTarefaEquipe */
  @property({ attribute: false }) obterTarefaEquipeStatus: 'idle' | 'loading' | 'success' | 'error' = 'idle';

  /** state obterTarefaEquipeError — error of the open task request, null when none; source obterTarefaEquipe */
  @property({ attribute: false }) obterTarefaEquipeError: ErrorState = null;

  /** state buscarResponsaveisDisponiveisStatus — status of the assignee search request; source buscarResponsaveisDisponiveis */
  @property({ attribute: false }) buscarResponsaveisDisponiveisStatus: 'idle' | 'loading' | 'success' | 'error' = 'idle';

  /** state buscarResponsaveisDisponiveisError — error of the assignee search request, null when none; source buscarResponsaveisDisponiveis */
  @property({ attribute: false }) buscarResponsaveisDisponiveisError: ErrorState = null;

  /** state trocarResponsavelTarefaStatus — status of the reassign command; source trocarResponsavelTarefa */
  @property({ attribute: false }) trocarResponsavelTarefaStatus: 'idle' | 'loading' | 'success' | 'error' = 'idle';

  /** state trocarResponsavelTarefaError — error of the reassign command, null when none; source trocarResponsavelTarefa */
  @property({ attribute: false }) trocarResponsavelTarefaError: ErrorState = null;

  /** state cancelarTarefaEquipeStatus — status of the cancel command; source cancelarTarefaEquipe */
  @property({ attribute: false }) cancelarTarefaEquipeStatus: 'idle' | 'loading' | 'success' | 'error' = 'idle';

  /** state cancelarTarefaEquipeError — error of the cancel command, null when none; source cancelarTarefaEquipe */
  @property({ attribute: false }) cancelarTarefaEquipeError: ErrorState = null;

  /** state scenary — the visible scene of the page; '' until the page shows its first scene */
  @property({ attribute: false }) scenary = '';

  private publish<M extends StateMember>(member: M, value: this[M]): void {
    (this as unknown as Record<string, unknown>)[member] = value;
    setState(`${KEY_PREFIX}${member}`, value);
    if (member === 'selectedTarefa') {
      this.syncUrlParam('tarefaId', this.selectedTarefa);
    }
    if (member === 'filtrosEquipe') {
      this.syncUrlParam('listaTarefasId', this.filtrosEquipe.listaId);
    }
  }

  private assignState(key: string, value: unknown): void {
    const member = STATE_MEMBER_BY_KEY[key];
    if (member) (this as unknown as Record<string, unknown>)[member] = value;
  }

  private syncUrlParam(name: string, value: string | null): void {
    try {
      if (!window.location.pathname.endsWith(PAGE_ROUTE_SUFFIX)) return;
      const url = new URL(window.location.href);
      if (value === null || value === '') {
        url.searchParams.delete(name);
      } else {
        url.searchParams.set(name, value);
      }
      history.replaceState(history.state, '', `${url.pathname}${url.search}${url.hash}`);
    } catch {
      // the URL is only a convenience; ignore failures
    }
  }

  private readonly onPopState = (): void => {
    if (window.location.pathname.endsWith(PAGE_ROUTE_SUFFIX)) {
      void this.startVisit();
    }
  };

  public connectedCallback(): void {
    super.connectedCallback();
    for (const key of DATA_KEYS) {
      const stored = getState(key);
      if (stored !== undefined) this.assignState(key, stored);
    }
    subscribe([...STATE_KEYS], this);
    window.addEventListener('popstate', this.onPopState);
    void this.startVisit();
  }

  public disconnectedCallback(): void {
    window.removeEventListener('popstate', this.onPopState);
    unsubscribe([...STATE_KEYS], this);
    super.disconnectedCallback();
  }

  public handleIcaStateChange(key: string, value: any): void {
    if (!(key in STATE_MEMBER_BY_KEY)) {
      super.handleIcaStateChange(key, value);
      return;
    }
    if (value === undefined) return;
    this.assignState(key, value);
    this.requestUpdate();
  }

  private readParam(name: string, useLocalStorage: boolean): string | null {
    const fromUrl = new URLSearchParams(window.location.search).get(name);
    if (fromUrl !== null && fromUrl !== '') return fromUrl;
    if (!useLocalStorage) return null;
    try {
      const stored = localStorage.getItem(`tarefas.tarefas_equipe.${name}`);
      if (stored !== null && stored !== '') return stored;
    } catch {
      // storage unavailable
    }
    return null;
  }

  private readEntryParams(): EntryParams {
    return {
      tarefaId: this.readParam('tarefaId', false),
      listaTarefasId: this.readParam('listaTarefasId', false),
      responsavelId: this.readParam('responsavelId', true),
    };
  }

  private applyEntryParams(params: EntryParams): void {
    if (params.listaTarefasId !== null) {
      this.publish('filtrosEquipe', { ...emptyFiltros(), listaId: params.listaTarefasId });
    }
    if (params.responsavelId !== null) {
      this.publish('trocarResponsavelTarefaDraft', { responsavelId: params.responsavelId });
    }
    if (params.tarefaId !== null) {
      this.publish('selectedTarefa', params.tarefaId);
    } else {
      this.publish('tarefa', null);
    }
  }

  private resetVisit(): void {
    this.publish('pageStatus', 'idle');
    this.publish('scenary', '');
    this.publish('carregarFiltrosEquipeStatus', 'idle');
    this.publish('carregarFiltrosEquipeError', null);
    this.publish('listarTarefasEquipeStatus', 'idle');
    this.publish('listarTarefasEquipeError', null);
    this.publish('obterTarefaEquipeStatus', 'idle');
    this.publish('obterTarefaEquipeError', null);
    this.publish('buscarResponsaveisDisponiveisStatus', 'idle');
    this.publish('buscarResponsaveisDisponiveisError', null);
    this.publish('trocarResponsavelTarefaStatus', 'idle');
    this.publish('trocarResponsavelTarefaError', null);
    this.publish('cancelarTarefaEquipeStatus', 'idle');
    this.publish('cancelarTarefaEquipeError', null);
    this.publish('filtrosEquipe', emptyFiltros());
    this.publish('trocarResponsavelTarefaDraft', emptyTrocarResponsavelTarefaDraft());
    this.publish('selectedTarefa', null);
  }

  private async startVisit(): Promise<void> {
    const params = this.readEntryParams();
    this.resetVisit();
    this.applyEntryParams(params);
    this.publish('pageStatus', 'loading');
    await Promise.all([this.carregarFiltrosEquipe(), this.listarTarefasEquipe(1, false)]);
    this.refreshPageStatus();
    if (params.tarefaId !== null) {
      await this.obterTarefaEquipe(params.tarefaId);
    }
  }

  private refreshPageStatus(): void {
    if (this.carregarFiltrosEquipeStatus === 'error' || this.listarTarefasEquipeStatus === 'error') {
      this.publish('pageStatus', 'error');
      return;
    }
    if (this.tarefas === null || this.tarefas.items.length === 0) {
      this.publish('pageStatus', 'empty');
      return;
    }
    this.publish('pageStatus', 'success');
  }

  private resetCommandResults(): void {
    this.publish('trocarResponsavelTarefaStatus', 'idle');
    this.publish('trocarResponsavelTarefaError', null);
    this.publish('cancelarTarefaEquipeStatus', 'idle');
    this.publish('cancelarTarefaEquipeError', null);
  }

  private unexpectedError(error: unknown, name?: string): NonNullable<ErrorState> {
    const errorName = name !== undefined ? name : error instanceof Error ? error.name : 'unknown';
    return { code: 'client.unexpected', message: '', details: { name: errorName } };
  }

  private responseError(error: ErrorState): NonNullable<ErrorState> {
    if (error) return error;
    return { code: 'client.unexpected', message: '', details: { name: 'noResponse' } };
  }

  /** scene — publishes the visible scene of the page; clears the results of the commands */
  public setScenario(value: string): void {
    this.resetCommandResults();
    this.publish('scenary', value);
  }

  /** draft — replaces the list filters (list, assignee, priority, status, due range; null leaves a filter off); only stores them, call listarTarefasEquipe() afterwards to load the first page with them */
  public setFiltrosEquipe(value: FiltrosEquipe): void {
    this.resetCommandResults();
    this.publish('filtrosEquipe', value);
  }

  /** draft — replaces the draft of the reassign command (responsavelId = the participant chosen by name); clears the results of the commands */
  public setTrocarResponsavelTarefaDraft(value: TrocarResponsavelTarefaDraft): void {
    this.resetCommandResults();
    this.publish('trocarResponsavelTarefaDraft', value);
  }

  /** request carregarFiltrosEquipe — loads the options of the list and assignee filters (the manager comes from the session); redraws listas and carregarFiltrosEquipeParticipantes (replace); no arguments, runs on load and can be called to reload the options */
  public async carregarFiltrosEquipe(): Promise<void> {
    if (this.carregarFiltrosEquipeStatus === 'loading') return;
    this.publish('carregarFiltrosEquipeStatus', 'loading');
    this.publish('carregarFiltrosEquipeError', null);
    try {
      const input: Input<'tarefas.tarefas_equipe.carregarFiltrosEquipe'> = {};
      const response = await execBff<Output<'tarefas.tarefas_equipe.carregarFiltrosEquipe'>>('tarefas.tarefas_equipe.carregarFiltrosEquipe', input, { mode: 'silent' });
      if (!response.ok || !response.data) {
        this.publish('carregarFiltrosEquipeError', this.responseError(response.error));
        this.publish('carregarFiltrosEquipeStatus', 'error');
        return;
      }
      this.publish('listas', response.data.listas);
      this.publish('carregarFiltrosEquipeParticipantes', response.data.participantes);
      this.publish('carregarFiltrosEquipeStatus', 'success');
    } catch (error) {
      this.publish('carregarFiltrosEquipeError', this.unexpectedError(error));
      this.publish('carregarFiltrosEquipeStatus', 'error');
    }
  }

  /** request listarTarefasEquipe — lists all organization tasks with the current filtrosEquipe, serving the list view and the board by status; redraws tarefas (replace, or append the next page when append is true) and contagemPorSituacao (replace); page = page to load (default 1), append = true for a "load more" (does nothing unless tarefas.hasMore, pass tarefas.page + 1) */
  public async listarTarefasEquipe(page: number = 1, append: boolean = false): Promise<void> {
    if (this.listarTarefasEquipeStatus === 'loading') return;
    const current = this.tarefas;
    if (append && (current === null || !current.hasMore)) return;
    this.publish('listarTarefasEquipeStatus', 'loading');
    this.publish('listarTarefasEquipeError', null);
    try {
      const f = this.filtrosEquipe;
      const input: Input<'tarefas.tarefas_equipe.listarTarefasEquipe'> = {
        ...(f.listaId !== null && f.listaId !== '' ? { listaId: f.listaId } : {}),
        ...(f.responsavelId !== null && f.responsavelId !== '' ? { responsavelId: f.responsavelId } : {}),
        ...(f.prioridade !== null ? { prioridade: f.prioridade } : {}),
        ...(f.status !== null ? { status: f.status } : {}),
        ...(f.prazoDe !== null && f.prazoDe !== '' ? { prazoDe: f.prazoDe } : {}),
        ...(f.prazoAte !== null && f.prazoAte !== '' ? { prazoAte: f.prazoAte } : {}),
        page,
        pageSize: PAGE_SIZE,
      };
      const response = await execBff<Output<'tarefas.tarefas_equipe.listarTarefasEquipe'>>('tarefas.tarefas_equipe.listarTarefasEquipe', input, { mode: 'silent' });
      if (!response.ok || !response.data) {
        this.publish('listarTarefasEquipeError', this.responseError(response.error));
        this.publish('listarTarefasEquipeStatus', 'error');
        return;
      }
      const loaded = response.data.tarefas;
      const previous = this.tarefas;
      if (append && previous !== null) {
        this.publish('tarefas', { ...loaded, items: [...previous.items, ...loaded.items] });
      } else {
        this.publish('tarefas', loaded);
      }
      this.publish('contagemPorSituacao', response.data.contagemPorSituacao);
      this.publish('listarTarefasEquipeStatus', 'success');
    } catch (error) {
      this.publish('listarTarefasEquipeError', this.unexpectedError(error));
      this.publish('listarTarefasEquipeStatus', 'error');
    }
  }

  /** request obterTarefaEquipe — opens one task with checklist, subtasks and history; this is also the selection: it publishes selectedTarefa and redraws tarefa (replace); tarefaId = id of the task picked in the list or board, null clears the selection and the opened task */
  public async obterTarefaEquipe(tarefaId: string | null): Promise<void> {
    if (this.obterTarefaEquipeStatus === 'loading') return;
    this.resetCommandResults();
    if (tarefaId === null || tarefaId === '') {
      this.publish('selectedTarefa', null);
      this.publish('tarefa', null);
      this.publish('obterTarefaEquipeError', null);
      this.publish('obterTarefaEquipeStatus', 'idle');
      return;
    }
    this.publish('selectedTarefa', tarefaId);
    this.publish('obterTarefaEquipeStatus', 'loading');
    this.publish('obterTarefaEquipeError', null);
    try {
      const input: Input<'tarefas.tarefas_equipe.obterTarefaEquipe'> = { tarefaId };
      const response = await execBff<Output<'tarefas.tarefas_equipe.obterTarefaEquipe'>>('tarefas.tarefas_equipe.obterTarefaEquipe', input, { mode: 'silent' });
      if (!response.ok || !response.data) {
        this.publish('tarefa', null);
        this.publish('obterTarefaEquipeError', this.responseError(response.error));
        this.publish('obterTarefaEquipeStatus', 'error');
        return;
      }
      this.publish('tarefa', response.data.tarefa);
      this.publish('obterTarefaEquipeStatus', 'success');
    } catch (error) {
      this.publish('obterTarefaEquipeError', this.unexpectedError(error));
      this.publish('obterTarefaEquipeStatus', 'error');
    }
  }

  /** request buscarResponsaveisDisponiveis — searches by name the active participants that accept tasks and can become the new assignee; redraws buscarResponsaveisDisponiveisParticipantes (replace); nome = typed part of the name, empty brings the first ones alphabetically */
